function pomoConfig(){ return { work:25*60, short:5*60, long:15*60, longEvery:4 }; }
function pomoInit(cfg){
  cfg=cfg||pomoConfig();
  return { phase:'work', left:cfg.work, running:false, done:0, cycles:0 };
}
function pomoNextPhase(st, cfg){
  cfg=cfg||pomoConfig();
  if(st.phase==='work'){
    var done=st.done+1;
    var isLong=(done % cfg.longEvery)===0;
    return { phase:isLong?'long':'short', left:isLong?cfg.long:cfg.short, running:st.running, done:done, cycles:st.cycles };
  }
  return { phase:'work', left:cfg.work, running:st.running, done:st.done, cycles:st.cycles+(st.phase==='long'?1:0) };
}
function pomoTick(st, cfg){
  cfg=cfg||pomoConfig();
  if(!st.running) return st;
  if(st.left>1) return { phase:st.phase, left:st.left-1, running:true, done:st.done, cycles:st.cycles };
  return pomoNextPhase({ phase:st.phase, left:0, running:true, done:st.done, cycles:st.cycles }, cfg);
}
function pomoToggle(st){ return { phase:st.phase, left:st.left, running:!st.running, done:st.done, cycles:st.cycles }; }
function pomoFmt(sec){
  var m=Math.floor(sec/60), s=sec%60;
  return (m<10?'0':'')+m+':'+(s<10?'0':'')+s;
}
function pomoProgress(st, cfg){
  cfg=cfg||pomoConfig();
  var total = st.phase==='work'?cfg.work : st.phase==='short'?cfg.short : cfg.long;
  return Math.round((1-st.left/total)*1000)/10;
}
function pomoLabel(phase){ return phase==='work'?'专注工作':phase==='short'?'短休息':'长休息'; }
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { pomoConfig:pomoConfig, pomoInit:pomoInit, pomoNextPhase:pomoNextPhase, pomoTick:pomoTick, pomoToggle:pomoToggle, pomoFmt:pomoFmt, pomoProgress:pomoProgress, pomoLabel:pomoLabel };
}
if (typeof window !== 'undefined') {
  window.PomodoroForgePure = { pomoConfig:pomoConfig, pomoInit:pomoInit, pomoNextPhase:pomoNextPhase, pomoTick:pomoTick, pomoToggle:pomoToggle, pomoFmt:pomoFmt, pomoProgress:pomoProgress, pomoLabel:pomoLabel };
}
